refentry.refsect1:
&reftitle.parameters;


  request


    Uma instância de Yaf_Request_Abstract a despachar.

&reftitle.returnvalues;

 A instância de Yaf_Response_Abstract em caso de sucesso,
 &false; em caso de falha, ou &null; se a aplicação não estiver inicializada.

  &reftitle.examples;

   Exemplo de Yaf_Dispatcher::dispatch


<?php
$app = new Yaf_Application(dirname(__FILE__) . "/conf/application.ini");
$app->bootstrap();

// Constrói uma requisição apontando para ProductController::detailAction e
// a despacha manualmente.
$request = new Yaf_Request_Http("/product/detail/id/42");

$response = Yaf_Dispatcher::getInstance()->dispatch($request);

if ($response instanceof Yaf_Response_Abstract) {
    $response->response();
}
?>
